import React from 'react'
import { type ITabsProps, Tabs } from '@Pimcore/components/tabs/tabs'
import { BaseView } from '@Pimcore/components/base-view/base-view'
import { Box, type BoxProps } from '../box/box'
import { useTranslation } from 'react-i18next'
import { isNonEmptyString } from '@sdk/utils'

export interface TabpanelItem {
  key?: string
  label?: string
  title?: string
  closable?: boolean
  children?: React.ReactNode
  [key: string]: any
}

export interface TabpanelProps {
  title?: string
  border?: boolean
  collapsible?: boolean
  collapsed?: boolean
  items: TabpanelItem[]
  tabPosition?: ITabsProps['tabPosition']
  hasStickyHeader?: boolean
  extra?: React.ReactNode
  extraPosition?: 'start' | 'end'
  theme?: 'default' | 'fieldset' | 'card-with-highlight' | 'border-highlight'
  contentPadding?: BoxProps['padding']
  onClose?: (tabKey: string) => void
  size?: ITabsProps['size']
  defaultActiveKey?: ITabsProps['defaultActiveKey']
  activeKey?: ITabsProps['activeKey']
  onChange?: ITabsProps['onChange']
}

export const Tabpanel = ({
  items,
  border,
  collapsed,
  collapsible,
  title,
  theme = 'card-with-highlight',
  contentPadding = 'none',
  hasStickyHeader = false,
  extra,
  extraPosition,
  onClose,
  size = 'small',
  defaultActiveKey,
  activeKey,
  onChange,
  ...props
}: TabpanelProps): React.JSX.Element => {
  const { t } = useTranslation()
  const tabItems: ITabsProps['items'] = items.map((item, index) => {
    const labelOrTitle = item.label ?? item.title
    const label = isNonEmptyString(labelOrTitle) ? t(labelOrTitle) : `Tab ${index + 1}`

    return {
      ...item,
      key: index.toString(),
      label,
      forceRender: true,
      closable: item.closable,
      children: <Box padding={ border === true ? 'small' : { x: 'none', y: 'small' } }>
        {item.children}
      </Box>
    }
  })

  const handleClose = (tabKey: string): void => {
    if (onClose !== undefined) {
      onClose(tabKey)
    }
  }

  return (
    <BaseView
      border={ border }
      collapsed={ collapsed }
      collapsible={ collapsible }
      contentPadding={ contentPadding }
      extra={ extra }
      extraPosition={ extraPosition }
      theme={ theme }
      title={ isNonEmptyString(title) ? t(title) : title }
    >
      <Tabs
        activeKey={ activeKey }
        defaultActiveKey={ defaultActiveKey }
        hasStickyHeader={ hasStickyHeader }
        items={ tabItems }
        noTabBarMargin
        onChange={ onChange }
        onClose={ onClose !== undefined ? handleClose : undefined }
        size={ size }
        tabPosition={ props.tabPosition }
      />
    </BaseView>
  )
}
